appendBritishAfricaGovernance("rhodesia","sections",[
  {id:"salisbury-understanding",title:"The Salisbury Understanding",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-r9j4q writer=g kind=revision created=2026-08-16T13:30:00-06:00 --><p>The <a href='salisbury-understanding.html'>Salisbury Understanding</a> is accepted institutional reconstruction for an unwritten bargain granting Rhodesian and federal authorities frontier discretion in exchange for secure borders, copper and rail traffic, restraint against cross-border war, and Crown loyalty.<sup class='canon-note' data-provenance='e'>[e]</sup> Its name, date, terms, participants, and legal effect remain open. The distinction between loyalty to the Crown and obedience to Parliament is compatible political interpretation.<sup class='canon-note' data-provenance='e'>[e]</sup></p><!-- altwwii-writer-block:end -->"}
]);
