appendBritishAfricaGovernance("british-africa","sections",[
  {id:"governance-architecture",title:"The frontier governance architecture",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-bs3t9 writer=g kind=revision created=2026-08-16T07:10:00-06:00 --><p>The Commonwealth African Reserve System, East African Defence and Development Commission, Salisbury Understanding, No Empty Flagstaff Doctrine, and their collective description as defensive-trusteeship machinery are accepted institutional development.<sup class='canon-note' data-provenance='e'>[e]</sup> Their enactments, jurisdictions, offices, budgets, and coordination remain governed by the linked articles.</p><!-- altwwii-writer-block:end -->"}
]);
